import React, { useRef } from 'react';
import { ConfirmDialog, confirmDialog } from 'primereact/confirmdialog';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';


export default function Headless() {
    const toast = useRef(null);

    const accept = () => {
        toast.current.show({ className: 'info', summary: 'Confirmed', detail: 'You have accepted', life: 3000 });
    };

    const reject = () => {
        toast.current.show({ className: 'warn', summary: 'Rejected', detail: 'You have rejected', life: 3000 });
    };

    const confirm1 = () => {
        confirmDialog({
            group: 'headless',
            message: 'Are you sure you want to proceed?',
            header: 'Confirmation',
            icon: 'pi pi-exclamation-triangle',
            defaultFocus: 'accept',
            rejectClassName: 'text',
            acceptClassName: 'danger',
            accept,
            reject
        });
    };

    return (
        <>
            <Toast ref={toast} />
            <ConfirmDialog
                size="extra-small"
                group="headless"
                content={({ headerRef, contentRef, footerRef, hide, message }) => (
                    <div className="w-100p fvc fxb column gp3 bd-primary pd12">
                        <div className="bd-circle bg-primary fxb fhc font-size64 mgtn24 pd4 rds-circle w60 h60">
                            <i className="pi pi-question font-size32 bold-font fg-white"></i>
                        </div>
                        <span className="font-size24 bold-font" ref={headerRef}>
                            {message.header}
                        </span>
                        <p className="mgt2" ref={contentRef}>
                            {message.message}
                        </p>
                        <div className="fxb fvc gp4 w-100p" ref={footerRef}>
                            <Button
                                label="Save"
                                onClick={(event) => {
                                    hide(event);
                                    accept();
                                }}
                                className="min-width8 w-100p"
                            ></Button>
                            <Button
                                label="Cancel"
                                outlined
                                onClick={(event) => {
                                    hide(event);
                                    reject();
                                }}
                                className="min-width8 w-100p"
                            ></Button>
                        </div>
                    </div>
                )}
            />
            <div className="fxb fvc gp5">
                <Button onClick={confirm1} icon="pi pi-check" label="Confirm"></Button>
            </div>
        </>
    )

}